class IndependentSlotsAlgorithm(QCAlgorithm):
    RED_CONSECUTIVE_DAYS = 3

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = [self.AddEquity(ticker, Resolution.Daily).Symbol for ticker in tickers]
        self.spy = self.Symbol("SPY")
        self.aapl = self.Symbol("AAPL")

        self.close_history = {symbol: [] for symbol in self.symbols}
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data: Slice):
        bars = {}

        for symbol in self.symbols:
            if symbol not in data.Bars:
                continue

            bar = data.Bars[symbol]
            bars[symbol] = bar

            history = self.close_history[symbol]
            previous_close = history[-1] if history else None
            history.append(float(bar.Close))
            if len(history) > 101:
                history.pop(0)

            if symbol == self.aapl:
                self.aapl_rsi.Update(bar.EndTime, bar.Close)

                if previous_close is None:
                    self.aapl_red_streak = 0
                elif bar.Close < previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

        if len(bars) != len(self.symbols):
            return

        spy_history = self.close_history[self.spy]
        spy_bar = bars[self.spy]
        aapl_bar = bars[self.aapl]

        strategy_a_ready = len(spy_history) >= 101
        strategy_b_ready = (
            self.aapl_rsi.IsReady and
            len(self.close_history[self.aapl]) >= 2
        )

        if strategy_a_ready and self.strategy_a_lot > 0:
            yesterday_sma = sum(spy_history[-101:-1]) / 100.0
            today_sma = sum(spy_history[-100:]) / 100.0
