                self.MarketOrder(self.spy, -self.strategy_a_lot)
                self.strategy_a_lot = 0

        if strategy_b_ready and self.strategy_b_lot > 0:
            if self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.strategy_b_lot)
                self.strategy_b_lot = 0

        if strategy_a_ready and self.strategy_a_lot == 0:
            yesterday_sma = sum(spy_history[-101:-1]) / 100.0
            today_sma = sum(spy_history[-100:]) / 100.0
            yesterday_close = spy_history[-2]
            today_close = spy_history[-1]

            if yesterday_close <= yesterday_sma and today_close > today_sma:
                quantity = int((float(self.Portfolio.TotalPortfolioValue) * 0.40) / float(spy_bar.Close))
                if quantity > 0:
                    self.MarketOrder(self.spy, quantity)
                    self.strategy_a_lot = quantity

        if strategy_b_ready and self.strategy_b_lot == 0:
            if self.aapl_red_streak >= self.RED_CONSECUTIVE_DAYS:
                if float(self.Portfolio.Cash) >= 20_000:
                    quantity = int(20_000 / float(aapl_bar.Close))
                    if quantity > 0:
                        self.MarketOrder(self.aapl, quantity)
                        self.strategy_b_lot = quantity
