from AlgorithmImports import *
from collections import deque


class IndependentSpyAndAaplStrategies(QCAlgorithm):

    RED_DAYS_REQUIRED = 3

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        }

        self.spy_symbol = self.symbols["SPY"]
        self.aapl_symbol = self.symbols["AAPL"]

        self.spy_closes = deque()
        self.spy_close_sum = 0.0

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi_changes = 0
        self.aapl_gain_sum = 0.0
        self.aapl_loss_sum = 0.0
        self.aapl_average_gain = None
        self.aapl_average_loss = None
        self.aapl_rsi = None

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if symbol in data.Bars:
                bars[ticker] = data.Bars[symbol]

        if "SPY" in bars:
            self._update_spy_sma_state(bars["SPY"].Close)

        if "AAPL" in bars:
            self._update_aapl_state(bars["AAPL"].Close)

        if len(bars) != len(self.symbols):
            return

        spy_close = bars["SPY"].Close
        aapl_close = bars["AAPL"].Close

        # Sells are evaluated before buys.
        if self.strategy_a_shares > 0 and self._spy_crosses_below_sma():
            self.MarketOrder(self.spy_symbol, -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi is not None and self.aapl_rsi > 60:
            self.MarketOrder(self.aapl_symbol, -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and self._spy_crosses_above_sma():
            shares = int((self.Portfolio.TotalPortfolioValue * 0.40) // spy_close)
            if shares > 0:
                self.MarketOrder(self.spy_symbol, shares)
                self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= self.RED_DAYS_REQUIRED:
            if self.Portfolio.Cash >= 20_000:
                shares = int(20_000 // aapl_close)
                if shares > 0:
                    self.MarketOrder(self.aapl_symbol, shares)
                    self.strategy_b_shares = shares

    def _update_spy_sma_state(self, close):
        self.spy_previous_close = self.spy_closes[-1] if self.spy_closes else None
        self.spy_previous_sma = (
            self.spy_close_sum / 100.0 if len(self.spy_closes) == 100 else None
        )

        if len(self.spy_closes) == 100:
            self.spy_close_sum -= self.spy_closes.popleft()

        self.spy_closes.append(close)
        self.spy_close_sum += close
        self.spy_current_sma = (
            self.spy_close_sum / 100.0 if len(self.spy_closes) == 100 else None
        )
        self.spy_current_close = close

    def _spy_crosses_above_sma(self):
        return (
            self.spy_previous_close is not None
            and self.spy_previous_sma is not None
            and self.spy_current_sma is not None
            and self.spy_previous_close <= self.spy_previous_sma
            and self.spy_current_close > self.spy_current_sma
        )

    def _spy_crosses_below_sma(self):
        return (
            self.spy_previous_close is not None
            and self.spy_previous_sma is not None
            and self.spy_current_sma is not None
            and self.spy_previous_close >= self.spy_previous_sma
            and self.spy_current_close < self.spy_current_sma
        )

    def _update_aapl_state(self, close):
        if self.aapl_previous_close is None:
            self.aapl_previous_close = close
            return

        change = close - self.aapl_previous_close

        if change < 0:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0

        gain = max(change, 0)
        loss = max(-change, 0)

        if self.aapl_rsi_changes < 14:
            self.aapl_gain_sum += gain
            self.aapl_loss_sum += loss
            self.aapl_rsi_changes += 1

            if self.aapl_rsi_changes == 14:
                self.aapl_average_gain = self.aapl_gain_sum / 14.0
                self.aapl_average_loss = self.aapl_loss_sum / 14.0
        else:
            self.aapl_average_gain = (
                (self.aapl_average_gain * 13.0) + gain
            ) / 14.0
            self.aapl_average_loss = (
                (self.aapl_average_loss * 13.0) + loss
            ) / 14.0

        if self.aapl_rsi_changes >= 14:
            if self.aapl_average_loss == 0:
                self.aapl_rsi = 100.0
            else:
                rs = self.aapl_average_gain / self.aapl_average_loss
                self.aapl_rsi = 100.0 - (100.0 / (1.0 + rs))

        self.aapl_previous_close = close
